/bin/bash -lc "python - <<'PY'
import pathlib,re,subprocess,json
files=[pathlib.Path(f) for f in subprocess.check_output(['git','ls-files','-z']).decode().split('\\0') if f]
patterns=[(r'(?:AKIA|ASIA)[A-Z0-9]{16}','<your-aws-access-key-id>'),(r'gh[pousr]_[A-Za-z0-9]{20,}|github_pat_[A-Za-z0-9_]{20,}','<your-github-token>'),(r'hf_[A-Za-z0-9]{20,}','<your-huggingface-token>')]
replacements={}
for f in files:
 s=f.read_bytes().decode('utf-8',errors='replace')
 for pat,placeholder in patterns:
  for m in re.finditer(pat,s):replacements[m.group()]=placeholder
 for l in s.splitlines():
  if 'AWS_SECRET_ACCESS_KEY' in l:
   for m in re.finditer(r'[A-Za-z0-9/+]{40}',l):replacements[m.group()]='<your-aws-secret-access-key>'
changed={}
for f in files:
 original=f.read_bytes(); updated=original
 for secret,placeholder in replacements.items():updated=updated.replace(secret.encode(),placeholder.encode())
 if updated"'!=original:
  f.write_bytes(updated);changed[str(f)]=sum(original.count(s.encode()) for s in replacements)
# Keep values in process memory only for exact-value verification, no secret report.
for f in files:
 b=f.read_bytes()
 assert not any(s.encode() in b for s in replacements),str(f)
print(json.dumps({'"'distinct_secrets_replaced':len(replacements),'replacements_by_file':changed,'exact_value_scan':'passed'},indent=2))
for x in json.load(open('/tmp/dclm-secrets-report.json')):
 if x['File'].startswith('exp_data/models'):
  l=pathlib.Path(x['File']).read_text().splitlines()[x['StartLine']-1]
  print('Model metadata false positive:',x['StartLine'],'contains training token count:',bool(re.search(r'tokens=\\d+',l)))
PY"

